"""W26 same-response classification; resident, pinned, read-only original inputs."""
import collections,csv,io,typing
import pandas as pd
from common import *
GROUPS={'Ribeirinhos':'riverside','Quilombolas':'quilombola','Indígenas':'indigenous','Não está inserida em nenhuma comunidade tradicional':'none','Outros':'other'}
LABELS={'riverside':'Em comunidade ribeirinha','quilombola':'Em comunidade quilombola','indigenous':'Em comunidade indígena','none':'Não inserida em comunidade tradicional (declaração)','other':'Em outra comunidade tradicional'}
def classify(value):
 if value is None or value=='':return {'state':'missing','groups':[]}
 if not isinstance(value,str):return {'state':'invalid_or_ambiguous','groups':[]}
 return {'state':'valid','groups':[GROUPS[value]]}if value in GROUPS else{'state':'invalid_or_ambiguous','groups':[]}
def main():
 i=Inputs();i.project=ResidentReader(R.parent,byte_budget=130000000);planned=read(A/'characterization_source_plan.json')['exactInputs'];w25=i.json('monitoramento_operacional_w25_teste/audit/distribution_manifest.json');controls={r['path']:r for r in i.json('monitoramento_operacional_w25_teste/audit/preservation.json')['controls']};cfg=i.json('equidade_w23_teste/config.json',controls['equidade_w23_teste/config.json']['sha256']);contract=i.json('equidade_w23_teste/'+cfg['sourceContract'],cfg['sourceContractSha256']);assert contract['sourceVariable']=='QT_MAT_BAS'and contract['enrollmentYear']==2025 and not contract['jointSexRaceAvailable']
 fm=i.json('equidade_w23_teste/private/'+cfg['derivedVersion']+'/frame_manifest.json');framepath='equidade_w23_teste/private/'+cfg['derivedVersion']+'/'+fm['file'];frame=pd.read_parquet(io.BytesIO(i.get(framepath,fm['sha256'])));assert frame.inep.is_unique;complete=frame[frame.status=='COMPLETED'].copy();ids=set(complete.inep)
 dictionary=list(csv.DictReader(io.StringIO(i.get(planned['dim_questions']['path'],planned['dim_questions']['sha256'],project=True).decode('utf-8-sig'))));q16=next(d for d in dictionary if d['codigo_pergunta']=='escola_comunidade_tradicional');assert q16['tipo_resposta']=='select'and q16['permitido_analise_interna'].startswith('Sim')and q16['campo_sensivel']=='Sim';assert set(q16['opcoes_possiveis'].split(' | '))==set(GROUPS)
 import gzip
 strategic=json.loads(gzip.decompress(i.get('monitoramento_operacional_w25_teste/web/data/strategic.json.gz',w25['files']['data/strategic.json.gz']['sha256'])));questions=strategic['questions'];qnums=[str(q['question_number'])for q in questions];assert len(qnums)==31
 source=i.get(planned['valid_response_wide']['path'],planned['valid_response_wide']['sha256'],project=True);reader=csv.DictReader(io.StringIO(source.decode('utf-8-sig')));selected={};outside=0;raw_counts=collections.Counter();audit_rows=[];duplicates=[]
 for r in reader:
  code=r['codigo_escola_limpo'].strip()
  if code not in ids:outside+=1;continue
  assert r['completed']=='1'or r['resposta_finalizada']=='Sim'
  if code in selected:duplicates.append(code);continue
  rawvalue=r['resposta_escola_comunidade_tradicional'];membership=classify(rawvalue);raw_counts[rawvalue]+=1;selected[code]={'characteristic':membership['groups'][0]if membership['state']=='valid'else membership['state'],**{'q'+str(q['question_number']):' '.join(r.get('resposta_'+q['p45_field'],'').split())or None for q in questions}}
  audit_rows.append({'inep':code,'sourceRecordHash':r['registro_hash'],'rawValue':rawvalue,**membership})
 assert not duplicates and set(selected)==ids,'Canonical response selection mismatch'
 numeric_comparisons=0;old_answer_comparisons=0
 for n in cfg['interfaceEnabledQuestions']:
  for code,value in zip(complete.inep,complete['q'+n]):
   original=None if pd.isna(value)else' '.join(str(value).split())or None
   assert original==selected[code]['q'+n],(code,n,'Different response selection');old_answer_comparisons+=1
 for column in ['characteristic']+['q'+n for n in qnums]:complete[column]=complete.inep.map(lambda k:selected[k][column])
 private=E/'private';private.mkdir(exist_ok=True);target=private/'characterized_responses.parquet';complete.to_parquet(target,index=False,compression='zstd');put(private/'characterization_raw_audit.json',{'releaseVersion':VERSION,'question':'16','sourceField':'resposta_escola_comunidade_tradicional','rows':audit_rows,'sourceHash':planned['valid_response_wide']['sha256']})
 source_catalog=i.json('editorial_integracao_teste/versions/'+VERSION+'/private/catalog.json',controls['editorial_integracao_teste/versions/'+VERSION+'/private/catalog.json']['sha256']);put(private/'catalog.json',source_catalog);meta=i.json('equidade_w23_teste/derived/'+cfg['derivedVersion']+'/metadata.json');put(private/'equity_metadata.json',meta)
 for path,name in [('equidade_w23_teste/tools/engine.py','frozen_equity.py'),('scripts/build_release_candidata_wash.py','frozen_canonical_source.py')]:
  body=i.get(path,controls[path]['sha256']if path in controls else None);(E/'tools'/name).write_bytes(body)
 counts={g:sum(1 for r in audit_rows if g in r['groups'])for g in LABELS};missing=sum(r['state']=='missing'for r in audit_rows);invalid=sum(r['state']=='invalid_or_ambiguous'for r in audit_rows);classification_version=digest(raw({'field':q16,'mapping':GROUPS,'source':planned['valid_response_wide']['sha256']}))[:16]
 policy={'internalProcessing':'AUTHORIZED_BY_EXISTING_DICTIONARY_SIM_USO_INTERNO','nominalAssociation':False,'publicDisclosure':'CONDITIONAL_AGGREGATE_SUPPRESSION_AND_HOMOLOGATION','smallNPolicy':'PENDING_PRIVACY_POLICY','threshold':None,'newIntersectionInstitutionalReview':'PENDING_BEFORE_EXTERNAL_DISCLOSURE','PUBLICATION_READY':False,'publication':'NOT_EXECUTED'}
 contract_out={'schema':'wash.w26.characterization.contract.v1','releaseVersion':VERSION,'classificationVersion':classification_version,'questionNumber':'16','sourceField':'escola_comunidade_tradicional','statement':q16['texto_pergunta'],'meaning':'School inserted in a traditional community, not attendance population (Q18), race of enrollments or Census differentiated location','responseType':'select','multiResponse':False,'required':None,'requiredEvidence':'Not present in frozen derived dictionary; not inferred from observed completeness','conditional':'NO_BRANCH_PROVEN; missing versus not shown is not identifiable','mapping':GROUPS,'labels':LABELS,'missingness':{'missing':missing,'invalidOrAmbiguous':invalid,'notShown':None,'explicitNegative':counts['none'],'other':counts['other']},'counts':counts,'completedCanonical':len(ids),'overlapSchools':0,'outsideCanonicalEligible':outside,'canonicalWideSameResponseComparisons':old_answer_comparisons,'policy':policy,'schoolResponseDate':'W25 omission unchanged','sourceDictionary':planned['dim_questions'],'sourceWide':planned['valid_response_wide'],'sourceJoined':{'path':framepath,'sha256':fm['sha256']},'basicEducationContractSHA256':cfg['sourceContractSha256']};put(A/'characterization_contract.json',contract_out)
 put(private/'manifest.json',{'frame':{'file':target.name,'bytes':target.stat().st_size,'sha256':sha(target),'rows':len(complete)},'releaseVersion':VERSION,'classificationVersion':classification_version,'questionColumns':qnums,'equityAllowed':cfg['interfaceEnabledQuestions'],'equityRestricted':cfg['restrictedQuestions'],'policy':policy,'catalogSHA256':sha(private/'catalog.json'),'equityMetadataSHA256':sha(private/'equity_metadata.json'),'basicEducationContractSHA256':cfg['sourceContractSha256'],'sources':{'dictionary':planned['dim_questions'],'wide':planned['valid_response_wide'],'joined':{'path':framepath,'sha256':fm['sha256']}},'frozenTools':{n:sha(E/'tools'/n)for n in ['frozen_equity.py','frozen_canonical_source.py']}})
 put(A/'private_build.json',{'status':'PASS_PRIVATE_CANONICAL_CLASSIFICATION','canonicalRows':len(ids),'uniqueSchools':complete.inep.nunique(),'counts':counts,'overlapSchools':0,'outsideCanonicalEligible':outside,'sameResponseComparisons':old_answer_comparisons,'privateFrameBytes':target.stat().st_size,'privateFrameSHA256':sha(target),'sourceWrites':False,'newExtraction':False,'newCensusJoin':False,'existingSameReleaseResponseLink':True,'publication':'NOT_EXECUTED'});i.flush();print(json.dumps({'status':'PASS_PRIVATE_CANONICAL_CLASSIFICATION','counts':counts,'schools':len(ids),'outsideCanonicalEligible':outside,'sameResponseComparisons':old_answer_comparisons,'privateBytes':target.stat().st_size},ensure_ascii=True),flush=True)
if __name__=='__main__':main()
